### 2. Recursive Implementation
Useful for academic contexts or when the logic maps naturally to recursion.

```cpp
/**
 * Helper recursive function.
 * @param left  Inclusive lower bound index.
 * @param right Exclusive upper bound index.
 */
template <typename T, typename Container>
std::optional<size_t> binary_search_recursive_helper(const Container& container, const T& target, size_t left, size_t right) {
    if (left >= right) {
        return std::nullopt; // Base case: empty range
    }

    size_t mid = left + (right - left) / 2;

    if (container[mid] == target) {
        return mid;
    } else if (container[mid] < target) {
        return binary_search_recursive_helper(container, target, mid + 1, right);
    } else {
        return binary_search_recursive_helper(container, target, left, mid);
    }
}

// Wrapper function to hide the left/right parameters from the caller
template <typename T, typename Container>
std::optional<size_t> binary_search_recursive(const Container& container, const T& target) {
    return binary_search_recursive_helper(container, target, 0, container.size());
}
```

